  'Welcome to AajExam! 🎉 Your free mock test is unlocked.': 'AajExam ಗೆ ಸ್ವಾಗತ! 🎉 ನಿಮ್ಮ ಉಚಿತ ಮಾಕ್ ಟೆಸ್ಟ್ ಅನ್‌ಲಾಕ್ ಆಗಿದೆ.',
