  'You\'re studying hard! Create a free account now to save your progress and get personalized tests.': 'ನೀವು ಕಷ್ಟಪಟ್ಟು ಓದುತ್ತಿದ್ದೀರಿ! ನಿಮ್ಮ ಪ್ರಗತಿ ಉಳಿಸಲು ಮತ್ತು ವೈಯಕ್ತಿಕ ಟೆಸ್ಟ್‌ಗಳನ್ನು ಪಡೆಯಲು ಈಗಲೇ ಉಚಿತ ಖಾತೆ ರಚಿಸಿ.',
