  'Your Target Exams': 'ನಿಮ್ಮ ಗುರಿ ಪರೀಕ್ಷೆಗಳು',
  'Your account, subscription, and wallet balance are completely safe. All your exam preparation data has been preserved on this platform.': 'ನಿಮ್ಮ ಖಾತೆ, ಚಂದಾದಾರಿಕೆ ಮತ್ತು ವ್ಯಾಲೆಟ್ ಬ್ಯಾಲೆನ್ಸ್ ಸಂಪೂರ್ಣ ಸುರಕ್ಷಿತವಾಗಿವೆ. ನಿಮ್ಮ ಎಲ್ಲಾ ಪರೀಕ್ಷೆ ಸಿದ್ಧತೆ ಡೇಟಾವನ್ನು ಈ ವೇದಿಕೆಯಲ್ಲಿ ಸಂರಕ್ಷಿಸಲಾಗಿದೆ.',
