  ', AajExam is 100% based on your knowledge and hard work. Everything you earn here is through your own effort. We follow all rules to make sure the platform is safe, fair, and honest for every student.': ', AajExam 100% ನಿಮ್ಮ ಜ್ಞಾನ ಮತ್ತು ಶ್ರಮವನ್ನು ಆಧರಿಸಿದೆ. ಇಲ್ಲಿ ನೀವು ಗಳಿಸುವುದೆಲ್ಲವೂ ನಿಮ್ಮದೇ ಪ್ರಯತ್ನದಿಂದ. ಪ್ರತಿ ವಿದ್ಯಾರ್ಥಿಗೆ ವೇದಿಕೆ ಸುರಕ್ಷಿತ, ನ್ಯಾಯಸಮ್ಮತ ಮತ್ತು ಪ್ರಾಮಾಣಿಕವಾಗಿರುವಂತೆ ನಾವು ಎಲ್ಲಾ ನಿಯಮಗಳನ್ನು ಪಾಲಿಸುತ್ತೇವೆ.',
  'A Government Registered Company (UDYAM)': 'ಸರ್ಕಾರಿ ನೋಂದಾಯಿತ ಕಂಪನಿ (UDYAM)',
  'A:': 'ಉ:',
  'Q:': 'ಪ್ರ:',
  'AajExam Team': 'AajExam ತಂಡ',
  'AajExam helps students across India prepare for government exams. We believe every student deserves good study material, no matter where they come from.': 'AajExam ದೇಶಾದ್ಯಂತದ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಸರ್ಕಾರಿ ಪರೀಕ್ಷೆಗಳಿಗೆ ತಯಾರಾಗಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. ಯಾವ ಹಿನ್ನೆಲೆಯಿಂದ ಬಂದಿದ್ದರೂ ಪ್ರತಿ ವಿದ್ಯಾರ್ಥಿಗೆ ಉತ್ತಮ ಅಧ್ಯಯನ ಸಾಮಗ್ರಿ ಸಿಗಬೇಕು ಎಂದು ನಾವು ನಂಬುತ್ತೇವೆ.',
  'AajExam is about your knowledge and your hard work. The more you study and practice, the better your score. Only your effort takes you to the top.': 'AajExam ನಿಮ್ಮ ಜ್ಞಾನ ಮತ್ತು ಶ್ರಮದ ಬಗ್ಗೆ. ನೀವು ಹೆಚ್ಚು ಓದಿ ಅಭ್ಯಾಸ ಮಾಡಿದಷ್ಟೂ ನಿಮ್ಮ ಸ್ಕೋರ್ ಉತ್ತಮವಾಗುತ್ತದೆ. ನಿಮ್ಮ ಪ್ರಯತ್ನ ಮಾತ್ರ ನಿಮ್ಮನ್ನು ಶಿಖರಕ್ಕೆ ಕರೆದೊಯ್ಯುತ್ತದೆ.',
  'About Us | Last Updated February 2026': 'ನಮ್ಮ ಬಗ್ಗೆ | ಕೊನೆಯ ನವೀಕರಣ ಫೆಬ್ರವರಿ 2026',
  'About the Founder': 'ಸ್ಥಾಪಕರ ಬಗ್ಗೆ',
  'All Subjects Covered': 'ಎಲ್ಲಾ ವಿಷಯಗಳು ಒಳಗೊಂಡಿವೆ',
  'All articles': 'ಎಲ್ಲಾ ಲೇಖನಗಳು',
  'All government exams': 'ಎಲ್ಲಾ ಸರ್ಕಾರಿ ಪರೀಕ್ಷೆಗಳು',
  'As a UDYAM registered entrepreneur, Sazid combines technical expertise with business acumen to create scalable, user-friendly educational solutions. His vision is to democratize access to high-quality government exam preparation resources, ensuring that students from all backgrounds have the tools they need to succeed in competitive examinations.': 'UDYAM ನೋಂದಾಯಿತ ಉದ್ಯಮಿಯಾಗಿ, ಸಾಜಿದ್ ತಾಂತ್ರಿಕ ಪರಿಣತಿ ಮತ್ತು ವ್ಯಾಪಾರ ಜಾಣ್ಮೆಯನ್ನು ಸೇರಿಸಿ ವಿಸ್ತರಿಸಬಹುದಾದ, ಬಳಕೆದಾರ ಸ್ನೇಹಿ ಶೈಕ್ಷಣಿಕ ಪರಿಹಾರಗಳನ್ನು ರಚಿಸುತ್ತಾರೆ. ಎಲ್ಲಾ ಹಿನ್ನೆಲೆಯ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಸ್ಪರ್ಧಾತ್ಮಕ ಪರೀಕ್ಷೆಗಳಲ್ಲಿ ಯಶಸ್ವಿಯಾಗಲು ಬೇಕಾದ ಸಾಧನಗಳು ಇರುವಂತೆ, ಉತ್ತಮ ಗುಣಮಟ್ಟದ ಸರ್ಕಾರಿ ಪರೀಕ್ಷೆ ಸಿದ್ಧತೆ ಸಂಪನ್ಮೂಲಗಳನ್ನು ಎಲ್ಲರಿಗೂ ಲಭ್ಯವಾಗಿಸುವುದು ಅವರ ದೃಷ್ಟಿ.',
  'Author': 'ಲೇಖಕ',
  'Blog Not Found': 'ಬ್ಲಾಗ್ ಸಿಗಲಿಲ್ಲ',
  'Browse All Blogs': 'ಎಲ್ಲಾ ಬ್ಲಾಗ್‌ಗಳನ್ನು ನೋಡಿ',
  'Can\'t find the answer you\'re looking for? Our support team is here to help!': 'ನೀವು ಹುಡುಕುತ್ತಿರುವ ಉತ್ತರ ಸಿಗಲಿಲ್ಲವೇ? ನಮ್ಮ ಬೆಂಬಲ ತಂಡ ಸಹಾಯ ಮಾಡಲು ಇಲ್ಲಿದೆ!',
  'Comprehensive exam preparation materials and practice tests.': 'ಸಮಗ್ರ ಪರೀಕ್ಷೆ ಸಿದ್ಧತೆ ಸಾಮಗ್ರಿಗಳು ಮತ್ತು ಅಭ್ಯಾಸ ಟೆಸ್ಟ್‌ಗಳು.',
