  'Email Address': 'ಇಮೇಲ್ ವಿಳಾಸ',
  'Enforced on the server — locked content shows a real upgrade gate, not just a hidden button': 'ಸರ್ವರ್‌ನಲ್ಲಿ ಜಾರಿಯಾಗುತ್ತದೆ — ಲಾಕ್ ಮಾಡಿದ ವಿಷಯ ಮರೆಮಾಡಿದ ಬಟನ್ ಅಲ್ಲ, ನಿಜವಾದ ಅಪ್‌ಗ್ರೇಡ್ ಗೇಟ್ ತೋರಿಸುತ್ತದೆ',
  'Error sending message. Please try again.': 'ಸಂದೇಶ ಕಳುಹಿಸುವಲ್ಲಿ ದೋಷ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
  'Everything you need to start preparing today, no card required.': 'ಇಂದೇ ತಯಾರಿ ಪ್ರಾರಂಭಿಸಲು ಬೇಕಾದ ಎಲ್ಲವೂ, ಕಾರ್ಡ್ ಬೇಡ.',
  'Exam preparation tips, guides & insights': 'ಪರೀಕ್ಷೆ ಸಿದ್ಧತೆ ಟಿಪ್ಸ್, ಮಾರ್ಗದರ್ಶಿಗಳು ಮತ್ತು ಒಳನೋಟಗಳು',
  'Failed to load blogs': 'ಬ್ಲಾಗ್‌ಗಳು ಲೋಡ್ ಆಗಲಿಲ್ಲ',
  'Feature': 'ವೈಶಿಷ್ಟ್ಯ',
  'Featured': 'ವಿಶೇಷ',
  'Find Us on Social Media': 'ಸಾಮಾಜಿಕ ಮಾಧ್ಯಮದಲ್ಲಿ ನಮ್ಮನ್ನು ಹುಡುಕಿ',
  'Find answers to common questions about AajExam platform, subscriptions, and exam preparation': 'AajExam ವೇದಿಕೆ, ಚಂದಾದಾರಿಕೆಗಳು ಮತ್ತು ಪರೀಕ್ಷೆ ಸಿದ್ಧತೆ ಬಗ್ಗೆ ಸಾಮಾನ್ಯ ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರ ಹುಡುಕಿ',
  'First, try clearing your browser cache and cookies, or try a different browser. If issues persist, contact our support team at {email} with details about the problem, your device, and browser information.': 'ಮೊದಲು, ನಿಮ್ಮ ಬ್ರೌಸರ್ ಕ್ಯಾಶ್ ಮತ್ತು ಕುಕೀಗಳನ್ನು ತೆರವುಗೊಳಿಸಿ ಅಥವಾ ಬೇರೆ ಬ್ರೌಸರ್ ಪ್ರಯತ್ನಿಸಿ. ಸಮಸ್ಯೆ ಮುಂದುವರಿದರೆ, ಸಮಸ್ಯೆ, ನಿಮ್ಮ ಸಾಧನ ಮತ್ತು ಬ್ರೌಸರ್ ವಿವರಗಳೊಂದಿಗೆ ನಮ್ಮ ಬೆಂಬಲ ತಂಡವನ್ನು {email} ನಲ್ಲಿ ಸಂಪರ್ಕಿಸಿ.',
  'Follow Us': 'ನಮ್ಮನ್ನು ಫಾಲೋ ಮಾಡಿ',
  'For Every Student': 'ಪ್ರತಿ ವಿದ್ಯಾರ್ಥಿಗಾಗಿ',
