  'Free forever': 'ಎಂದಿಗೂ ಉಚಿತ',
  'Free practice quizzes': 'ಉಚಿತ ಅಭ್ಯಾಸ ರಸಪ್ರಶ್ನೆಗಳು',
  'Full feature comparison': 'ಪೂರ್ಣ ವೈಶಿಷ್ಟ್ಯ ಹೋಲಿಕೆ',
  'Full-Stack Developer | Educational Technology Expert | UDYAM Registered Entrepreneur': 'ಫುಲ್-ಸ್ಟ್ಯಾಕ್ ಡೆವಲಪರ್ | ಶೈಕ್ಷಣಿಕ ತಂತ್ರಜ್ಞಾನ ತಜ್ಞ | UDYAM ನೋಂದಾಯಿತ ಉದ್ಯಮಿ',
  'Get Started Now': 'ಈಗಲೇ ಪ್ರಾರಂಭಿಸಿ',
  'Get started free': 'ಉಚಿತವಾಗಿ ಪ್ರಾರಂಭಿಸಿ',
