  'You decide how fast or slow you want to study. No pressure.': 'ನೀವು ಎಷ್ಟು ವೇಗವಾಗಿ ಅಥವಾ ನಿಧಾನವಾಗಿ ಓದಬೇಕು ಎಂದು ನೀವೇ ನಿರ್ಧರಿಸಿ. ಒತ್ತಡವಿಲ್ಲ.',
  'See Your Progress': 'ನಿಮ್ಮ ಪ್ರಗತಿ ನೋಡಿ',
