  'Practice as many tests as you want with full step-by-step answers.': 'ಹಂತ-ಹಂತದ ಉತ್ತರಗಳೊಂದಿಗೆ ನಿಮಗೆ ಬೇಕಾದಷ್ಟು ಟೆಸ್ಟ್‌ಗಳನ್ನು ಅಭ್ಯಾಸ ಮಾಡಿ.',
  'Invite your friends to AajExam and earn cash rewards when they upgrade to PRO.': 'ನಿಮ್ಮ ಸ್ನೇಹಿತರನ್ನು AajExam ಗೆ ಆಹ್ವಾನಿಸಿ ಮತ್ತು ಅವರು PRO ಗೆ ಅಪ್‌ಗ್ರೇಡ್ ಆದಾಗ ನಗದು ರಿವಾರ್ಡ್‌ಗಳನ್ನು ಗಳಿಸಿ.',
  'Sign Up': 'ಸೈನ್ ಅಪ್',
  'Create your free account using your mobile number or email. It takes less than a minute to get started.': 'ನಿಮ್ಮ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಅಥವಾ ಇಮೇಲ್ ಬಳಸಿ ಉಚಿತ ಖಾತೆ ರಚಿಸಿ. ಪ್ರಾರಂಭಿಸಲು ಒಂದು ನಿಮಿಷಕ್ಕಿಂತ ಕಡಿಮೆ ಸಮಯ ಸಾಕು.',
