  'Step 3': 'ಹಂತ 3',
  'Step 4': 'ಹಂತ 4',
  'Step 5': 'ಹಂತ 5',
  'Pick a Plan': 'ಪ್ಲಾನ್ ಆಯ್ಕೆಮಾಡಿ',
  'Choose a free or paid plan based on what you need. Your plan decides how many PYQ papers and mock tests you can unlock.': 'ನಿಮ್ಮ ಅಗತ್ಯಕ್ಕೆ ತಕ್ಕಂತೆ ಉಚಿತ ಅಥವಾ ಪಾವತಿ ಪ್ಲಾನ್ ಆಯ್ಕೆಮಾಡಿ. ನೀವು ಎಷ್ಟು PYQ ಪತ್ರಿಕೆಗಳು ಮತ್ತು ಮಾಕ್ ಟೆಸ್ಟ್‌ಗಳನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಬಹುದು ಎಂಬುದನ್ನು ನಿಮ್ಮ ಪ್ಲಾನ್ ನಿರ್ಧರಿಸುತ್ತದೆ.',
  'Free Plan': 'ಉಚಿತ ಪ್ಲಾನ್',
