  'Pro Plan': 'Pro ಪ್ಲಾನ್',
  'Every year PYQ + unlimited mocks': 'ಪ್ರತಿ ವರ್ಷದ PYQ + ಅನಿಯಮಿತ ಮಾಕ್‌ಗಳು',
  'Take Practice Quizzes': 'ಅಭ್ಯಾಸ ರಸಪ್ರಶ್ನೆಗಳನ್ನು ಬರೆಯಿರಿ',
  'Answer MCQ questions made by experts. Practice PYQ papers, topic-wise quizzes, subject tests and the Daily Challenge to get exam-ready.': 'ತಜ್ಞರು ರಚಿಸಿದ MCQ ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರಿಸಿ. ಪರೀಕ್ಷೆಗೆ ಸಿದ್ಧರಾಗಲು PYQ ಪತ್ರಿಕೆಗಳು, ಟಾಪಿಕ್ ವಾರು ರಸಪ್ರಶ್ನೆಗಳು, ವಿಷಯ ಟೆಸ್ಟ್‌ಗಳು ಮತ್ತು ದೈನಂದಿನ ಸವಾಲನ್ನು ಅಭ್ಯಾಸ ಮಾಡಿ.',
  'Track Your Progress': 'ನಿಮ್ಮ ಪ್ರಗತಿ ಟ್ರ್ಯಾಕ್ ಮಾಡಿ',
  'See how many questions you got right and how fast you answered. Check your leaderboard rank, All India Rank and Exam Readiness Score to improve in every subject.': 'ಎಷ್ಟು ಪ್ರಶ್ನೆಗಳು ಸರಿ ಮತ್ತು ಎಷ್ಟು ವೇಗವಾಗಿ ಉತ್ತರಿಸಿದಿರಿ ಎಂದು ನೋಡಿ. ಪ್ರತಿ ವಿಷಯದಲ್ಲಿ ಸುಧಾರಿಸಲು ನಿಮ್ಮ ಲೀಡರ್‌ಬೋರ್ಡ್ ರ‍್ಯಾಂಕ್, ಆಲ್ ಇಂಡಿಯಾ ರ‍್ಯಾಂಕ್ ಮತ್ತು ಪರೀಕ್ಷೆ ಸಿದ್ಧತೆ ಸ್ಕೋರ್ ನೋಡಿ.',
  'Invite your friends to AajExam. When a friend upgrades to PRO, you get a cash reward in your account.': 'ನಿಮ್ಮ ಸ್ನೇಹಿತರನ್ನು AajExam ಗೆ ಆಹ್ವಾನಿಸಿ. ಸ್ನೇಹಿತ PRO ಗೆ ಅಪ್‌ಗ್ರೇಡ್ ಆದಾಗ, ನಿಮ್ಮ ಖಾತೆಯಲ್ಲಿ ನಗದು ರಿವಾರ್ಡ್ ಸಿಗುತ್ತದೆ.',
  'Only Your Knowledge Counts': 'ನಿಮ್ಮ ಜ್ಞಾನ ಮಾತ್ರ ಲೆಕ್ಕಕ್ಕೆ',
  'You win by knowing more, not by luck. Hard work and study is all that matters.': 'ನೀವು ಹೆಚ್ಚು ತಿಳಿದುಕೊಳ್ಳುವುದರಿಂದ ಗೆಲ್ಲುತ್ತೀರಿ, ಅದೃಷ್ಟದಿಂದ ಅಲ್ಲ. ಶ್ರಮ ಮತ್ತು ಅಧ್ಯಯನ ಮಾತ್ರ ಮುಖ್ಯ.',
  'Earn With Referrals': 'ರೆಫರಲ್‌ಗಳಿಂದ ಗಳಿಸಿ',
  'Invite friends and earn real cash rewards when they upgrade to PRO.': 'ಸ್ನೇಹಿತರನ್ನು ಆಹ್ವಾನಿಸಿ ಮತ್ತು ಅವರು PRO ಗೆ ಅಪ್‌ಗ್ರೇಡ್ ಆದಾಗ ನಿಜವಾದ ನಗದು ರಿವಾರ್ಡ್‌ಗಳನ್ನು ಗಳಿಸಿ.',
